import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import { resources } from "@/i18n/resources";

/**
 * Translations: src/i18n/locales/<language>/<section>.json, English ("en", US spelling) is the source.
 * Missing keys fall back to the language family (en-GB → en), then to English, so a half-translated
 * catalog never shows raw keys. resources.ts is generated by scripts/i18n-index.mjs.
 * Usage in a screen: const { t } = useTranslation("onboarding"); t("signIn.title")
 */
export const NAMESPACES = ["common", "onboarding", "reels", "posts", "photoshoot", "marketing", "business", "plans", "recovery"] as const;

// eslint-disable-next-line import/no-named-as-default-member -- i18next documents i18n.use(); the named `use` export trips the hooks rule
void i18n.use(initReactI18next).init({
  resources,
  lng: "en",
  fallbackLng: (code) => (code.includes("-") ? [code.split("-")[0], "en"] : ["en"]),
  ns: NAMESPACES as unknown as string[],
  defaultNS: "common",
  interpolation: { escapeValue: false }, // React already escapes
  returnNull: false,
});

export default i18n;

/** Dates in the app's language: formatDate(d, { day: "numeric", month: "short" }). */
export function formatDate(date: Date | string, options: Intl.DateTimeFormatOptions) {
  return new Intl.DateTimeFormat(i18n.language, options).format(typeof date === "string" ? new Date(date) : date);
}

export function formatNumber(n: number, options?: Intl.NumberFormatOptions) {
  return new Intl.NumberFormat(i18n.language, options).format(n);
}
